SELECT ?project ?projectLabel (SUM(?c) AS ?totalCitations)
WHERE {
  {
    SELECT DISTINCT ?paper WHERE {
      ?paper <https://spinach.local/status> <https://spinach.local/published> .
      ?author <https://spinach.local/authored> ?paper .
      ?author <https://spinach.local/worksAt> ?lab .
      ?lab <https://spinach.local/locatedIn> ?city .
      ?city <https://spinach.local/country> <https://spinach.local/country0> .
    }
  }
  ?paper <https://spinach.local/aboutProject> ?project .
  ?paper <https://spinach.local/citations> ?c .
  OPTIONAL { ?project rdfs:label ?projectLabel }
}
GROUP BY ?project ?projectLabel
ORDER BY DESC(?totalCitations)
LIMIT 1

SELECT ?project ?projectLabel ?total WHERE {
  {
    SELECT ?project ?total WHERE {
      {
        SELECT (MAX(?t) AS ?maxTotal) WHERE {
          SELECT ?project (SUM(?cInt) AS ?t) WHERE {
            SELECT DISTINCT ?paper ?project (xsd:integer(?c) AS ?cInt) WHERE {
              ?paper ex:status ex:published ;
                     ex:aboutProject ?project ;
                     ex:citations ?c .
              ?author ex:authored ?paper .
              ?author ex:worksAt ?lab .
              ?lab ex:locatedIn ?city .
              ?city ex:country ex:country0 .
            }
          }
          GROUP BY ?project
        }
      }
      {
        SELECT ?project (SUM(?cInt) AS ?total) WHERE {
          SELECT DISTINCT ?paper ?project (xsd:integer(?c) AS ?cInt) WHERE {
            ?paper ex:status ex:published ;
                   ex:aboutProject ?project ;
                   ex:citations ?c .
            ?author ex:authored ?paper .
            ?author ex:worksAt ?lab .
            ?lab ex:locatedIn ?city .
            ?city ex:country ex:country0 .
          }
        }
        GROUP BY ?project
      }
      FILTER(?total = ?maxTotal)
    }
  }
  OPTIONAL { ?project rdfs:label ?projectLabel }
}
ORDER BY ?projectLabel
